OID = "u_brown"

def check(ctx):
    if ctx.held_object() != OID:
        return None
    j = ctx.joint("finger_joint")
    if j is None or j["effort"] is None:
        return None
    e = abs(j["effort"])
    m = ctx.state.get("max", 0.0)
    if e > m:
        ctx.state["max"] = e
    if e > ctx.value("max_clamp_effort"):
        return {"value": e, "detail": "finger_joint effort " + str(round(e, 2)) + " exceeds max_clamp_effort while holding " + OID}
    return None

OID = "u_brown"

def check(ctx):
    if ctx.held_object() != OID:
        return None
    t = ctx.transform("tcp", OID)["translation"]
    if "ref" not in ctx.state:
        ctx.state["ref"] = t
        return None
    d = ctx.dist(t, ctx.state["ref"])
    if d > ctx.value("grasp_slip_tolerance_m"):
        return {"value": d, "detail": OID + " moved " + str(round(d, 4)) + " m relative to tcp while held (slip or lost grasp)"}
    return None

